create table if not exists public.tamp_activity_events(id uuid primary key default gen_random_uuid(),actor_user_id uuid,actor_email text,event_type text not null,action text not null,entity_type text,entity_id text,summary text,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create index if not exists tamp_activity_events_created_idx on public.tamp_activity_events(created_at desc);
create table if not exists public.student_complaints(id uuid primary key default gen_random_uuid(),user_id uuid,email text,subject text not null,message text not null,status text not null default 'open' check(status in ('open','in_progress','resolved','closed')),admin_reply text,replied_at timestamptz,replied_by uuid,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.admin_members(id uuid primary key default gen_random_uuid(),user_id uuid not null unique,assigned_by uuid,active boolean not null default true,permissions jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.push_subscriptions(id uuid primary key default gen_random_uuid(),user_id uuid not null,endpoint text not null unique,p256dh text,auth text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.site_videos(id uuid primary key default gen_random_uuid(),title text not null,url text not null,description text,published boolean not null default true,sort_order integer not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
do $$ begin if not exists(select 1 from information_schema.columns where table_schema='public' and table_name='profiles' and column_name='role') then alter table public.profiles add column role text not null default 'student'; end if; end $$;
alter table public.tamp_activity_events enable row level security;
alter table public.student_complaints enable row level security;
alter table public.admin_members enable row level security;
alter table public.push_subscriptions enable row level security;
alter table public.site_videos enable row level security;
drop policy if exists "tamp events insert own" on public.tamp_activity_events;
create policy "tamp events insert own" on public.tamp_activity_events for insert to authenticated with check(actor_user_id=(select auth.uid()) or actor_user_id is null);
drop policy if exists "tamp events read admins" on public.tamp_activity_events;
create policy "tamp events read admins" on public.tamp_activity_events for select to authenticated using(exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.role='admin'));
drop policy if exists "complaints insert own" on public.student_complaints;
create policy "complaints insert own" on public.student_complaints for insert to authenticated with check(user_id=(select auth.uid()));
drop policy if exists "complaints read own or admin" on public.student_complaints;
create policy "complaints read own or admin" on public.student_complaints for select to authenticated using(user_id=(select auth.uid()) or exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.role='admin'));
drop policy if exists "admin members owner read" on public.admin_members;
create policy "admin members owner read" on public.admin_members for select to authenticated using(user_id=(select auth.uid()) or exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.role='admin'));
drop policy if exists "push subscriptions own" on public.push_subscriptions;
create policy "push subscriptions own" on public.push_subscriptions for all to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()));
drop policy if exists "site videos public read" on public.site_videos;
create policy "site videos public read" on public.site_videos for select to anon,authenticated using(published=true or exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.role='admin'));
drop policy if exists "site videos admins write" on public.site_videos;
create policy "site videos admins write" on public.site_videos for all to authenticated using(exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.role='admin')) with check(exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.role='admin'));
do $$ begin if to_regclass('public.notifications') is not null then alter table public.notifications enable row level security; execute 'drop policy if exists "notifications own or admin read" on public.notifications'; execute 'create policy "notifications own or admin read" on public.notifications for select to authenticated using(user_id=(select auth.uid()) or exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.role=''admin''))'; end if; end $$;
create or replace function public.admin_assign_admin(p_email text,p_permissions jsonb) returns jsonb language plpgsql security definer set search_path=public as $$ declare target uuid; begin if not exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.role='admin') then raise exception 'Administrator access required'; end if; select id into target from public.profiles where lower(email)=lower(trim(p_email)) limit 1; if target is null then raise exception 'No TAMP account exists for this email'; end if; insert into public.admin_members(user_id,assigned_by,permissions) values(target,(select auth.uid()),coalesce(p_permissions,'{}'::jsonb)) on conflict(user_id) do update set active=true,assigned_by=excluded.assigned_by,permissions=excluded.permissions,updated_at=now(); update public.profiles set role='admin',updated_at=now() where id=target; return jsonb_build_object('user_id',target,'email',p_email); end $$;
revoke execute on function public.admin_assign_admin(text,jsonb) from public,anon;
grant execute on function public.admin_assign_admin(text,jsonb) to authenticated;
create or replace function public.admin_reply_complaint(p_complaint_id uuid,p_reply text) returns jsonb language plpgsql security definer set search_path=public as $$ declare c public.student_complaints%rowtype; begin if not exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.role='admin') then raise exception 'Administrator access required'; end if; select * into c from public.student_complaints where id=p_complaint_id; if c.id is null then raise exception 'Complaint not found'; end if; update public.student_complaints set admin_reply=p_reply,replied_at=now(),replied_by=(select auth.uid()),status='resolved',updated_at=now() where id=p_complaint_id; if c.user_id is not null and to_regclass('public.notifications') is not null then insert into public.notifications(user_id,title,body,data) values(c.user_id,'TAMP replied to your complaint',p_reply,jsonb_build_object('complaint_id',c.id,'url','/notifications')); end if; return jsonb_build_object('ok',true); end $$;
revoke execute on function public.admin_reply_complaint(uuid,text) from public,anon;
grant execute on function public.admin_reply_complaint(uuid,text) to authenticated;
insert into public.site_videos(title,url,description,sort_order) select 'How TAMP works','https://www.youtube.com/watch?v=ywZXpfdqg1o','A short orientation to the TAMP learning experience.',1 where not exists(select 1 from public.site_videos);